/**
 * Motifs for catalog modules in R05 Natur & miljö (0.28). Same geometry format as motifs.ts.
 */
import type { Motif, Part, Role } from './motifs';

const p = (d: string, r: Role, hue?: number): Part => ({ t: 'path', d, r, hue });
const c = (cx: number, cy: number, rad: number, r: Role, hue?: number): Part => ({ t: 'circle', cx, cy, rad, r, hue });
const q = (x: number, y: number, w: number, h: number, r: Role, rx = 1.5, hue?: number): Part => ({ t: 'rect', x, y, w, h, rx, r, hue });
const G = { green: 115, leaf: 95, orange: 26, red: 6, yellow: 46, blue: 210, sky: 195, brown: 28, sand: 40, purple: 285, pink: 330, slate: 220 } as const;
const fig = (x: number, y: number, s: number, r: Role): Part[] => [c(x, y - 14 * s, 5 * s, r), p(`M${x - 7 * s} ${y + 12 * s} V${y - 2 * s} C${x - 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 2 * s} V${y + 12 * s} Z`, r)];
const sun = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'main', G.yellow), ...[0, 1, 2, 3, 4, 5, 6, 7].map((i) => { const a = (i / 8) * Math.PI * 2; return p(`M${(x + Math.cos(a) * (r + 3)).toFixed(1)} ${(y + Math.sin(a) * (r + 3)).toFixed(1)} L${(x + Math.cos(a) * (r + 7)).toFixed(1)} ${(y + Math.sin(a) * (r + 7)).toFixed(1)}`, 'line'); })];
const cloud = (x: number, y: number, s: number, r: Role = 'light', hue?: number): Part => p(`M${x - 16 * s} ${y + 6 * s} C${x - 24 * s} ${y + 6 * s} ${x - 24 * s} ${y - 6 * s} ${x - 15 * s} ${y - 5 * s} C${x - 14 * s} ${y - 14 * s} ${x - 2 * s} ${y - 16 * s} ${x + 2 * s} ${y - 9 * s} C${x + 8 * s} ${y - 14 * s} ${x + 18 * s} ${y - 10 * s} ${x + 16 * s} ${y - 2 * s} C${x + 24 * s} ${y - 2 * s} ${x + 24 * s} ${y + 6 * s} ${x + 16 * s} ${y + 6 * s} Z`, r, hue);
const drop = (x: number, y: number, s: number, r: Role = 'main', hue: number = G.blue): Part => p(`M${x} ${y - 7 * s} C${x - 5 * s} ${y} ${x - 5 * s} ${y + 4 * s} ${x} ${y + 4 * s} C${x + 5 * s} ${y + 4 * s} ${x + 5 * s} ${y} ${x} ${y - 7 * s} Z`, r, hue);
const mountain = (x: number, y: number, w: number, h: number, r: Role = 'main', hue?: number, snow = true): Part[] => [p(`M${x} ${y + h} L${x + w / 2} ${y} L${x + w} ${y + h} Z`, r, hue), ...(snow ? [p(`M${x + w / 2} ${y} L${x + w / 2 - w * 0.13} ${y + h * 0.26} L${x + w / 2} ${y + h * 0.2} L${x + w / 2 + w * 0.13} ${y + h * 0.26} Z`, 'light')] : [])];
const tree = (x: number, y: number, s: number, hue: number = G.green): Part[] => [q(x - 2 * s, y, 4 * s, 14 * s, 'line', 1), c(x, y - 4 * s, 11 * s, 'main', hue)];
const conifer = (x: number, y: number, s: number, hue: number = G.green): Part[] => [q(x - 2 * s, y + 18 * s, 4 * s, 6 * s, 'line', 1), p(`M${x} ${y - 6 * s} L${x + 10 * s} ${y + 10 * s} H${x + 5 * s} L${x + 13 * s} ${y + 19 * s} H${x - 13 * s} L${x - 5 * s} ${y + 10 * s} H${x - 10 * s} Z`, 'main', hue)];
const fish = (x: number, y: number, s: number, r: Role = 'main', hue?: number): Part[] => [p(`M${x - 14 * s} ${y} C${x - 8 * s} ${y - 9 * s} ${x + 6 * s} ${y - 9 * s} ${x + 10 * s} ${y} C${x + 6 * s} ${y + 9 * s} ${x - 8 * s} ${y + 9 * s} ${x - 14 * s} ${y} Z M${x + 9 * s} ${y} L${x + 18 * s} ${y - 7 * s} V${y + 7 * s} Z`, r, hue), c(x - 8 * s, y - 2 * s, 1.4 * s, 'line')];
const bird = (x: number, y: number, s: number, r: Role = 'main', hue?: number): Part[] => [p(`M${x - 12 * s} ${y + 4 * s} C${x - 10 * s} ${y - 6 * s} ${x + 2 * s} ${y - 8 * s} ${x + 6 * s} ${y - 2 * s} L${x + 13 * s} ${y - 1 * s} L${x + 7 * s} ${y + 2 * s} C${x + 4 * s} ${y + 9 * s} ${x - 6 * s} ${y + 10 * s} ${x - 12 * s} ${y + 4 * s} Z`, r, hue), c(x + 4 * s, y - 3 * s, 1.2 * s, 'line'), p(`M${x - 6 * s} ${y} C${x - 2 * s} ${y + 4 * s} ${x + 2 * s} ${y + 4 * s} ${x + 3 * s} ${y + 2 * s}`, 'line')];
const leaf = (x: number, y: number, s: number, r: Role = 'main', hue: number = G.green): Part[] => [p(`M${x} ${y + 14 * s} C${x - 12 * s} ${y + 4 * s} ${x - 10 * s} ${y - 10 * s} ${x} ${y - 14 * s} C${x + 10 * s} ${y - 10 * s} ${x + 12 * s} ${y + 4 * s} ${x} ${y + 14 * s} Z`, r, hue), p(`M${x} ${y - 10 * s} V${y + 14 * s}`, 'line')];
const flower = (x: number, y: number, s: number, hue: number = G.pink): Part[] => [p(`M${x} ${y + 6 * s} V${y + 22 * s}`, 'line'), ...[0, 1, 2, 3, 4].map((i) => { const a = (i / 5) * Math.PI * 2 - Math.PI / 2; return c(x + Math.cos(a) * 5 * s, y + Math.sin(a) * 5 * s, 4 * s, 'main', hue); }), c(x, y, 3 * s, 'main', G.yellow)];
const mushroom = (x: number, y: number, s: number, hue: number = G.brown): Part[] => [q(x - 4 * s, y, 8 * s, 14 * s, 'light', 3 * s), p(`M${x - 14 * s} ${y + 2 * s} C${x - 14 * s} ${y - 12 * s} ${x + 14 * s} ${y - 12 * s} ${x + 14 * s} ${y + 2 * s} Z`, 'main', hue)];
const wave = (y: number, r: Role = 'main', hue: number = G.blue): Part => p(`M2 ${y} C10 ${y - 4} 14 ${y + 4} 22 ${y} C30 ${y - 4} 34 ${y + 4} 42 ${y} C50 ${y - 4} 54 ${y + 4} 62 ${y} V62 H2 Z`, r, hue);
const globe = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'main', G.blue), p(`M${x - r * 0.6} ${y - r * 0.3} C${x - r * 0.2} ${y - r * 0.6} ${x} ${y} ${x + r * 0.3} ${y - r * 0.2} C${x + r * 0.6} ${y - r * 0.4} ${x + r * 0.7} ${y + r * 0.2} ${x + r * 0.3} ${y + r * 0.4} C${x} ${y + r * 0.5} ${x - r * 0.4} ${y + r * 0.3} ${x - r * 0.6} ${y - r * 0.3} Z`, 'accent', G.green)];
const doc = (x: number, y: number, w: number, h: number, lines = 3): Part[] => [q(x, y, w, h, 'light', 2), p(Array.from({ length: lines }, (_, i) => `M${x + 5} ${y + 8 + i * 7} H${x + w - (i === lines - 1 ? 12 : 5)}`).join(' '), 'line')];
const thermo = (x: number, y: number, fill: number, hue: number = G.red): Part[] => [q(x - 4, y, 8, 34, 'light', 4), c(x, y + 38, 7, 'accent', hue), q(x - 2, y + 34 - fill, 4, fill + 2, 'accent', 2, hue)];
const check = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} L${x - 1 * s} ${y + 4 * s} L${x + 6 * s} ${y - 4 * s}`, 'line');
const star = (x: number, y: number, r: number, role: Role, hue?: number): Part => { const pts = Array.from({ length: 10 }, (_, i) => { const a = -Math.PI / 2 + (i * Math.PI) / 5; const rr = i % 2 ? r * 0.45 : r; return `${(x + Math.cos(a) * rr).toFixed(1)} ${(y + Math.sin(a) * rr).toFixed(1)}`; }); return p(`M${pts.join(' L')} Z`, role, hue); };
const arrowR = (x1: number, x2: number, y: number): Part => p(`M${x1} ${y} H${x2} M${x2 - 4} ${y - 4} L${x2} ${y} L${x2 - 4} ${y + 4}`, 'line');
const map = (r: Role = 'light'): Part[] => [p('M4 12 L22 6 L42 12 L60 6 V52 L42 58 L22 52 L4 58 Z', r), p('M22 6 V52 M42 12 V58', 'line')];
const continent = (d: string, hue: number = G.green): Part[] => [q(4, 4, 56, 56, 'main', 6, G.blue), p(d, 'main', hue)];

